-- CDIR Administration v1. PostgreSQL 15+. Run through npm run db:migrate.
-- Firebase Authentication owns identity; no password columns or Firestore rules here.
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE seasons (id uuid PRIMARY KEY,name text NOT NULL UNIQUE,"startsAt" date NOT NULL,"endsAt" date NOT NULL,status text NOT NULL CHECK(status IN ('OPEN','CLOSED')),current boolean NOT NULL DEFAULT false,CHECK("startsAt"<"endsAt"),CHECK(NOT current OR status='OPEN'));
CREATE UNIQUE INDEX one_current_season ON seasons(current) WHERE current;
CREATE TABLE teams (id uuid PRIMARY KEY,"seasonId" uuid NOT NULL REFERENCES seasons(id),name text NOT NULL,category text NOT NULL,modality text NOT NULL,branch text NOT NULL,active boolean NOT NULL,UNIQUE(id,"seasonId"),UNIQUE("seasonId",name));
CREATE TABLE players (id uuid PRIMARY KEY,name text NOT NULL,"birthDate" date NOT NULL,email text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',active boolean NOT NULL);
CREATE TABLE guardians (id uuid PRIMARY KEY,name text NOT NULL,email text NOT NULL,phone text NOT NULL);
CREATE TABLE player_seasons (id uuid PRIMARY KEY,"playerId" uuid NOT NULL REFERENCES players(id),"seasonId" uuid NOT NULL REFERENCES seasons(id),"teamId" uuid,"licenseTeamId" uuid,number integer CHECK(number BETWEEN 0 AND 99),status text NOT NULL CHECK(status IN ('ACTIVE','INACTIVE')),UNIQUE("playerId","seasonId"),UNIQUE(id,"seasonId"),FOREIGN KEY("teamId","seasonId") REFERENCES teams(id,"seasonId"),FOREIGN KEY("licenseTeamId","seasonId") REFERENCES teams(id,"seasonId"));
CREATE TABLE guardian_links (id uuid PRIMARY KEY,"playerId" uuid NOT NULL REFERENCES players(id),"guardianId" uuid NOT NULL REFERENCES guardians(id),"seasonId" uuid NOT NULL REFERENCES seasons(id),relationship text NOT NULL,legal boolean NOT NULL,pickup boolean NOT NULL,UNIQUE("playerId","guardianId","seasonId"),FOREIGN KEY("playerId","seasonId") REFERENCES player_seasons("playerId","seasonId"));
CREATE TABLE coaches (id uuid PRIMARY KEY,name text NOT NULL,email text NOT NULL,phone text NOT NULL,qualification text NOT NULL);
CREATE TABLE coach_teams (id uuid PRIMARY KEY,"coachId" uuid NOT NULL REFERENCES coaches(id),"teamId" uuid NOT NULL,"seasonId" uuid NOT NULL,function text NOT NULL,FOREIGN KEY("teamId","seasonId") REFERENCES teams(id,"seasonId"),UNIQUE("coachId","teamId"));
CREATE TABLE venues (id uuid PRIMARY KEY,name text NOT NULL,address text NOT NULL,space text NOT NULL,UNIQUE(name,space));
CREATE TABLE sessions (id uuid PRIMARY KEY,"seasonId" uuid NOT NULL REFERENCES seasons(id),"teamId" uuid NOT NULL,"venueId" uuid NOT NULL REFERENCES venues(id),"startsAt" timestamptz NOT NULL,"endsAt" timestamptz NOT NULL,kind text NOT NULL,status text NOT NULL CHECK(status IN ('SCHEDULED','CANCELLED')),CHECK("startsAt"<"endsAt"),UNIQUE(id,"seasonId"),FOREIGN KEY("teamId","seasonId") REFERENCES teams(id,"seasonId"),EXCLUDE USING gist ("venueId" WITH =,tstzrange("startsAt","endsAt",'[)') WITH &&) WHERE(status='SCHEDULED'));
CREATE TABLE cross_trainings (id uuid PRIMARY KEY,"seasonId" uuid NOT NULL REFERENCES seasons(id),"playerSeasonId" uuid NOT NULL,"destinationSessionId" uuid NOT NULL,"sourceSessionId" uuid,reason text NOT NULL,FOREIGN KEY("playerSeasonId","seasonId") REFERENCES player_seasons(id,"seasonId"),FOREIGN KEY("destinationSessionId","seasonId") REFERENCES sessions(id,"seasonId"),FOREIGN KEY("sourceSessionId","seasonId") REFERENCES sessions(id,"seasonId"),UNIQUE("playerSeasonId","destinationSessionId"),CHECK("sourceSessionId" IS NULL OR "sourceSessionId"<>"destinationSessionId"));
CREATE TABLE attendance (id uuid PRIMARY KEY,"sessionId" uuid NOT NULL REFERENCES sessions(id),"playerSeasonId" uuid NOT NULL REFERENCES player_seasons(id),status text NOT NULL CHECK(status IN ('PRESENT','ABSENT','EXCUSED')),UNIQUE("sessionId","playerSeasonId"));
CREATE TABLE forms (id uuid PRIMARY KEY,name text NOT NULL,version integer NOT NULL CHECK(version>0),fields jsonb NOT NULL,active boolean NOT NULL,UNIQUE(name,version));
CREATE TABLE events (id uuid PRIMARY KEY,"seasonId" uuid NOT NULL REFERENCES seasons(id),title text NOT NULL,slug text NOT NULL UNIQUE,kind text NOT NULL,description text NOT NULL,location text NOT NULL,"startsAt" timestamptz NOT NULL,"endsAt" timestamptz NOT NULL,capacity integer NOT NULL CHECK(capacity>0),price numeric(12,2) NOT NULL CHECK(price>=0),status text NOT NULL CHECK(status IN ('DRAFT','PUBLISHED','ARCHIVED')),"registrationOpen" boolean NOT NULL,"formId" uuid REFERENCES forms(id),"imageUrl" text NOT NULL DEFAULT '',CHECK("startsAt"<"endsAt"),CHECK(NOT "registrationOpen" OR (status='PUBLISHED' AND "formId" IS NOT NULL)),UNIQUE(id,"seasonId"));
CREATE TABLE applications (id uuid PRIMARY KEY,"seasonId" uuid NOT NULL REFERENCES seasons(id),"eventId" uuid NOT NULL,name text NOT NULL,"birthDate" date NOT NULL,email text NOT NULL,phone text NOT NULL,status text NOT NULL CHECK(status IN ('PENDING','CONFIRMED','REJECTED')),"createdAt" timestamptz NOT NULL,"requestKey" uuid NOT NULL UNIQUE,"privacyVersion" text NOT NULL,"privacyAccepted" boolean NOT NULL CHECK("privacyAccepted"),"imageConsent" boolean NOT NULL,answers jsonb NOT NULL,FOREIGN KEY("eventId","seasonId") REFERENCES events(id,"seasonId"));
CREATE UNIQUE INDEX unique_active_application ON applications("eventId",lower(email),lower(name)) WHERE status<>'REJECTED';
CREATE TABLE invoices (id uuid PRIMARY KEY,"seasonId" uuid NOT NULL REFERENCES seasons(id),"playerSeasonId" uuid NOT NULL,concept text NOT NULL,amount numeric(12,2) NOT NULL CHECK(amount>0),"dueDate" date NOT NULL,status text NOT NULL CHECK(status IN ('PENDING','PAID')),"paidAt" timestamptz,FOREIGN KEY("playerSeasonId","seasonId") REFERENCES player_seasons(id,"seasonId"),CHECK((status='PAID')=("paidAt" IS NOT NULL)));
CREATE TABLE bank_accounts (id uuid PRIMARY KEY,"playerSeasonId" uuid NOT NULL UNIQUE REFERENCES player_seasons(id),holder text NOT NULL,"holderDocument" text NOT NULL,"ibanEncrypted" text NOT NULL,last4 char(4) NOT NULL,"mandateReference" text NOT NULL UNIQUE,"mandateDate" date NOT NULL);
CREATE TABLE contents (id uuid PRIMARY KEY,kind text NOT NULL CHECK(kind IN ('NEWS','SPONSOR','DOCUMENT','PAGE')),title text NOT NULL,body text NOT NULL,url text NOT NULL,status text NOT NULL CHECK(status IN ('DRAFT','PUBLISHED')),"seasonId" uuid REFERENCES seasons(id));
CREATE TABLE members (id uuid PRIMARY KEY,uid text NOT NULL UNIQUE,name text NOT NULL,email text NOT NULL,role text NOT NULL CHECK(role IN ('ADMIN','SECRETARY','COORDINATOR','COACH','TREASURY','EDITOR','DIRECTOR')),"teamIds" uuid[] NOT NULL DEFAULT '{}',active boolean NOT NULL);
CREATE UNIQUE INDEX member_email ON members(lower(email));
CREATE TABLE audit_logs (id uuid PRIMARY KEY,at timestamptz NOT NULL,actor text NOT NULL,"actorUid" text NOT NULL,action text NOT NULL,detail text NOT NULL);
CREATE TABLE files (id uuid PRIMARY KEY,"ownerPlayerId" uuid NOT NULL REFERENCES players(id),name text NOT NULL,mime text NOT NULL,size integer NOT NULL CHECK(size BETWEEN 1 AND 5242880),"storagePath" text NOT NULL UNIQUE,"createdAt" timestamptz NOT NULL);
CREATE INDEX players_name ON players(lower(name));
CREATE INDEX sessions_team_date ON sessions("teamId","startsAt");
CREATE INDEX applications_review ON applications("seasonId",status);
CREATE INDEX events_visibility ON events(status,"startsAt");
CREATE INDEX audit_date ON audit_logs(at DESC);
-- Audit records cannot be edited or deleted through ordinary SQL writes.
CREATE FUNCTION cdir_audit_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit records are append-only'; END $$;
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION cdir_audit_immutable();
-- Forms referenced by an event keep their content and version; activation may change.
CREATE FUNCTION cdir_form_version_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (NEW.name<>OLD.name OR NEW.version<>OLD.version OR NEW.fields<>OLD.fields) AND EXISTS(SELECT 1 FROM events WHERE "formId"=OLD.id) THEN RAISE EXCEPTION 'Create a new form version'; END IF; RETURN NEW; END $$;
CREATE TRIGGER form_version_guard BEFORE UPDATE ON forms FOR EACH ROW EXECUTE FUNCTION cdir_form_version_guard();
